SELECT
FROM cultural_artifacts a INNER JOIN museums m ON a.museum_id = m.id WHERE a.status = 'ONLINE'
AND ( a.name LIKE CONCAT('%', #{keyword}, '%') OR a.origin LIKE CONCAT('%', #{keyword}, '%') OR a.description LIKE CONCAT('%', #{keyword}, '%') OR m.name LIKE CONCAT('%', #{keyword}, '%') )
AND a.dynasty = #{dynasty}
AND a.material = #{material}
AND a.artifact_type = #{type}
ORDER BY a.id ASC

mapper.update:
UPDATE cultural_artifacts
SET image_url = #{imageUrl}
WHERE id = #{id}
  AND (image_url IS NULL OR TRIM(image_url) = '')
